// Build Report — daily Telegram summary (New York day). Pure rules, no AI.
// Always one message: publications, performance of the last 24h per platform, top Reel, earnings, why below the
// publishing target (when fewer Reels than publish_max_per_day) and the Factory pipeline.

const cfgRows = $('Load Config').all().map(i => i.json ?? {});
const cfgVal = (key, def) => {
  const r = cfgRows.find(x => x.key === key);
  if (!r) return def;
  if (r.value_number !== null && r.value_number !== undefined && r.value_number !== '') return Number(r.value_number);
  return r.value_string ?? def;
};
const maxPerDay = Number(cfgVal('publish_max_per_day', 1)) || 1;
const enabled = Number(cfgVal('publish_enabled', 0)) ? 1 : 0;
const minViews = Number(cfgVal('factory_min_views', 250)) || 0;

const tz = 'America/New_York';
const nyNow = $now.setZone(tz);
const today = nyNow.toFormat('yyyy-MM-dd');
const nyDate = iso => (iso ? DateTime.fromISO(String(iso)).setZone(tz).toFormat('yyyy-MM-dd') : '');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const isTest = p => String(p.status_reason ?? '').startsWith('forced');

const posts = $('Get Posts').all().map(i => i.json ?? {}).filter(p => p.post_key);
const eligible = $('Get Eligible').all().map(i => i.json ?? {}).filter(c => c.candidate_key);
const errors = $('Get Errors').all().map(i => i.json ?? {})
  .filter(r => r.run_id && Date.now() - Date.parse(r.started_at ?? '') <= 24 * 3.6e6);

const published = posts.filter(p => p.status === 'PUBLISHED' && nyDate(p.published_at) === today);
const ready = posts.filter(p => p.status === 'READY' && !isTest(p));
const madeToday = posts.filter(p => !isTest(p) && nyDate(p.created_at) === today);
const count = st => madeToday.filter(p => p.status === st).length;
const failedPub = posts.filter(p => p.status === 'PUBLISH_FAILED' && nyDate(p.updated_at) === today);
const staleToday = posts.filter(p => p.status === 'STALE' && nyDate(p.updated_at) === today);
const usable = eligible.filter(c => c.platform === 'twitch' && (Number(c.views) || 0) >= minViews);

const lines = [];
const ok = published.length >= maxPerDay;
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
lines.push(`${published.length ? (ok ? '✅' : '🟡') : '⚠️'} <b>US VIRAL — ${nyNow.setLocale('it').toFormat('d LLL')}</b> (New York)`);

lines.push('', '📤 <b>Pubblicazioni</b>');
lines.push(`Pubblicati oggi: <b>${published.length}/${maxPerDay}</b>`);
for (const p of published) lines.push(`• ${esc(p.creator_name)} — ${esc(p.title)}${p.ig_permalink ? `\n${esc(p.ig_permalink)}` : ''}`);
lines.push('', `Pronti per i prossimi slot: ${ready.length}`);

// Views of the last 24h per platform, from the Analytics (04) snapshots: for every Reel, latest total now minus
// latest total 24h ago (0 if it was not out yet). Snapshots are every 6h, so the window is approximate.
const DAY = 24 * 3.6e6;
const nowMs = Date.now();
const snaps = $('Get Metrics').all().map(i => i.json ?? {})
  .filter(s => s.post_key && Number.isFinite(Date.parse(s.captured_at)) && s.views !== null && s.views !== undefined)
  .map(s => ({ ...s, platform: s.platform || 'instagram', t: Date.parse(s.captured_at), views: Number(s.views) || 0 }));
const postByKey = new Map(posts.map(p => [p.post_key, p]));
const outAt = (p, platform) => Date.parse((platform === 'youtube' ? p?.yt_published_at : null) || p?.published_at || '');
const series = new Map();
for (const s of snaps) {
  const k = `${s.platform}|${s.post_key}`;
  if (!series.has(k)) series.set(k, []);
  series.get(k).push(s);
}
// Total views of one Reel on one platform at time t (latest snapshot <= t).
const viewsAt = (list, platform, t) => {
  const before = list.filter(s => s.t <= t);
  if (before.length) return before.reduce((a, b) => (b.t > a.t ? b : a)).views;
  const out = outAt(postByKey.get(list[0].post_key), platform);
  if (Number.isFinite(out) && out > t) return 0;          // not out yet at t
  return list.reduce((a, b) => (b.t < a.t ? b : a)).views; // out but not measured yet: first snapshot
};
const gains = {};      // platform -> { today, yesterday }
const perPost = new Map();
for (const [k, list] of series) {
  const [platform, postKey] = k.split('|');
  const g = gains[platform] ??= { today: 0, yesterday: 0 };
  const d0 = Math.max(0, viewsAt(list, platform, nowMs) - viewsAt(list, platform, nowMs - DAY));
  const d1 = Math.max(0, viewsAt(list, platform, nowMs - DAY) - viewsAt(list, platform, nowMs - 2 * DAY));
  g.today += d0;
  g.yesterday += d1;
  perPost.set(postKey, (perPost.get(postKey) ?? 0) + d0);
}
const fmt = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
// Followers / subscribers gained in 24h per platform (viral_account_metrics; rows without platform are Instagram).
const followers = $('Get Followers').all().map(i => i.json ?? {})
  .filter(r => Number.isFinite(Date.parse(r.captured_at)) && r.followers_count !== null && r.followers_count !== undefined)
  .map(r => ({ platform: r.platform || 'instagram', t: Date.parse(r.captured_at), n: Number(r.followers_count) }));
const followDelta = platform => {
  const list = followers.filter(r => r.platform === platform).sort((a, b) => b.t - a.t);
  const latest = list[0];
  const dayAgo = list.find(r => r.t <= nowMs - DAY);
  return latest && dayAgo ? latest.n - dayAgo.n : null;
};
const followText = (platform, word) => {
  const d = followDelta(platform);
  return d === null ? '' : ` · ${d >= 0 ? '+' : ''}${d} ${word}`;
};

const rows = [
  ['Instagram', 'instagram', followText('instagram', 'follower')],
  ['YouTube', 'youtube', followText('youtube', 'iscritti')],
  ['Facebook', 'facebook', followText('facebook', 'follower')],
  ['TikTok', 'tiktok', ''],
];
const missing = { facebook: 'nessun dato ancora', tiktok: 'API non ancora collegata' };
lines.push('', '📊 <b>Performance ultime 24h</b>');
let total = 0, totalY = 0;
for (const [label, key, extra] of rows) {
  const g = gains[key];
  if (!g) { lines.push(`${label}: — (${missing[key] ?? 'nessun dato'})`); continue; }
  total += g.today; totalY += g.yesterday;
  lines.push(`${label}: <b>${fmt(g.today)}</b> views${extra}`);
}
const pct = totalY ? ` (ieri ${fmt(totalY)}, ${total >= totalY ? '+' : ''}${Math.round((total - totalY) / totalY * 100)}%)` : '';
lines.push('', `Totale: <b>${fmt(total)}</b> views${pct}`);

const top = [...perPost.entries()].sort((a, b) => b[1] - a[1])[0];
if (top && top[1] > 0) {
  const p = postByKey.get(top[0]) ?? {};
  lines.push('', '🔥 <b>Top contenuto</b>', `${esc(p.creator_name)} — “${esc(p.meme_caption || p.hook || p.title)}”`, `${fmt(top[1])} views (tutti i social)`);
}

// Earnings: only real figures read from the platforms (Analytics 04), never views x RPM estimates.
// Facebook reports them by day, 1-2 days late: the latest day available is shown.
const earn = $('Get Followers').all().map(i => i.json ?? {})
  .filter(r => r.earnings_usd !== null && r.earnings_usd !== undefined && Number.isFinite(Date.parse(r.captured_at)))
  .sort((a, b) => Date.parse(b.captured_at) - Date.parse(a.captured_at));
const fbEarn = earn.find(r => (r.platform || '') === 'facebook');
const usd = n => '$' + Number(n).toFixed(2);
lines.push('', '💰 <b>Guadagno (ultimo giorno disponibile)</b>');
lines.push(`Facebook: ${fbEarn ? `<b>${usd(fbEarn.earnings_usd)}</b>` : '— (dato non disponibile)'}`);
lines.push('Instagram: — (nessun guadagno diretto né API dei ricavi)');
lines.push('YouTube: — (non ancora monetizzato)');
lines.push('TikTok: — (API in attesa di approvazione; Creator Rewards non disponibile in Italia)');
lines.push(`Totale: <b>${usd(fbEarn ? fbEarn.earnings_usd : 0)}</b>`);

if (!ok) {
  const why = [];
  if (!enabled) why.push('publish_enabled = 0 (pubblicazione spenta)');
  for (const p of failedPub) why.push(`pubblicazione fallita: ${esc(p.creator_name)} — ${esc(String(p.error ?? '').slice(0, 200))}`);
  if (count('SKIPPED')) why.push(`Claude ha scartato ${plural(count('SKIPPED'), 'clip', 'clip')}`);
  if (count('FAILED')) why.push(plural(count('FAILED'), 'render/trascrizione fallita', 'render/trascrizioni fallite'));
  if (staleToday.length) why.push(`${plural(staleToday.length, 'Reel diventato', 'Reel diventati')} STALE prima della pubblicazione`);
  if (!madeToday.length && !ready.length) {
    why.push(usable.length
      ? `${usable.length} clip idonee ma bloccate (creator già usato nelle ultime ore o già montate)`
      : `nessuna clip Twitch idonea con almeno ${minViews} views`);
  }
  if (errors.length) why.push(`${plural(errors.length, 'errore', 'errori')} nei workflow nelle ultime 24h (vedi viral_runs)`);
  if (!why.length) why.push('nessun problema trovato: probabilmente non c\'era un Reel pronto all\'ora degli slot');
  lines.push('', '⚠️ <b>Perché siamo sotto il target di pubblicazione</b>', ...why.map(w => `• ${w}`));
}

lines.push('', '🏭 <b>Pipeline oggi</b>');
lines.push(`Factory avviate: ${madeToday.length}`);
lines.push(`Completate con successo: ${count('READY') + count('PUBLISHED')}`);
lines.push(`Clip idonee disponibili ora: ${eligible.length}`);

return [{
  json: {
    ny_date: today,
    published_today: published.length,
    max_per_day: maxPerDay,
    ready: ready.length,
    eligible_now: eligible.length,
    errors_24h: errors.length,
    chat_id: String(cfgVal('telegram_chat_id', '')),
    text: lines.join('\n'),
  },
}];
